"use client";

import { useRef } from "react";
import {
  BrainIcon,
  ChevronDownIcon,
  ClockIcon,
  HistoryIcon,
} from "@/components/icons";
import { CONVERSATION_DETAILS } from "@/lib/mock-data";
import type { ChatMessage } from "@/types";
import { Composer } from "../Composer";
import { Markdown } from "../Markdown";
import { useApp } from "../AppContext";

function StatusPill() {
  return (
    <div className="flex h-7 items-center gap-1.5 rounded-full bg-bg-2 px-2.5 text-fg-muted">
      <ClockIcon size={13} />
      <span className="h-1.5 w-1.5 rounded-full bg-bg-6" />
    </div>
  );
}

function HeaderModel({ label }: { label: string }) {
  return (
    <button
      type="button"
      className="flex h-7 items-center gap-1.5 rounded-full bg-bg-2 px-2.5 text-[13px] text-fg-secondary transition-colors hover:bg-bg-hover hover:text-fg"
    >
      <BrainIcon size={13} />
      <span>{label}</span>
      <ChevronDownIcon size={11} className="text-fg-muted" />
    </button>
  );
}

function ViewSteps({ steps }: { steps: number }) {
  return (
    <button
      type="button"
      className="my-2 inline-flex items-center gap-2 rounded-[8px] px-2 py-1 text-[13px] text-fg-secondary transition-colors hover:bg-bg-hover"
    >
      <HistoryIcon size={14} className="text-fg-muted" />
      <span>View Steps</span>
      <span className="text-fg-muted">· {steps}</span>
      <ChevronDownIcon size={12} className="-rotate-90 text-fg-muted" />
    </button>
  );
}

function Message({ message }: { message: ChatMessage }) {
  if (message.role === "user") {
    return (
      <div className="mb-6 flex justify-end">
        <div className="max-w-[78%] rounded-[14px] bg-message-user px-4 py-2.5 text-[15px] leading-relaxed text-fg">
          {message.content}
        </div>
      </div>
    );
  }
  return (
    <div className="mb-6">
      {message.steps ? <ViewSteps steps={message.steps} /> : null}
      <Markdown content={message.content} />
    </div>
  );
}

export function ConversationScreen() {
  const { activeConversationId } = useApp();
  const scrollRef = useRef<HTMLDivElement>(null);
  const convo = activeConversationId
    ? CONVERSATION_DETAILS[activeConversationId]
    : null;

  if (!convo) {
    return (
      <div className="grid h-full place-items-center text-fg-muted">
        Conversation not found
      </div>
    );
  }

  const scrollToBottom = () => {
    scrollRef.current?.scrollTo({
      top: scrollRef.current.scrollHeight,
      behavior: "smooth",
    });
  };

  return (
    <div className="flex h-full flex-col">
      <header className="flex h-[52px] shrink-0 items-center justify-between gap-3 px-5">
        <div className="flex min-w-0 items-center gap-2">
          <span className="text-[16px] leading-none">{convo.emoji}</span>
          <h2 className="truncate text-[15px] font-semibold text-fg">
            {convo.title}
          </h2>
        </div>
        <div className="flex items-center gap-2">
          <StatusPill />
          <HeaderModel label={convo.modelLabel} />
        </div>
      </header>

      <div ref={scrollRef} className="relative flex-1 overflow-y-auto">
        <div className="mx-auto max-w-[768px] px-5 py-6">
          {convo.messages.map((m) => (
            <Message key={m.id} message={m} />
          ))}
        </div>
      </div>

      <div className="relative px-5 pb-5">
        <button
          type="button"
          aria-label="Scroll to bottom"
          onClick={scrollToBottom}
          className="absolute -top-5 left-1/2 flex h-9 w-9 -translate-x-1/2 items-center justify-center rounded-full border border-border-base bg-bg-2 text-fg-secondary shadow-lg transition-colors hover:bg-bg-hover hover:text-fg"
        >
          <ChevronDownIcon size={16} />
        </button>
        <div className="mx-auto max-w-[768px]">
          <Composer
            placeholder={convo.composerPlaceholder}
            permissionLabel={convo.permissionLabel}
            showModel={false}
            glow
          />
        </div>
      </div>
    </div>
  );
}
