"use client";

import { useState } from "react";
import { SearchIcon } from "@/components/icons";
import { CONVERSATIONS } from "@/lib/mock-data";
import { useApp } from "./AppContext";

export function SearchOverlay() {
  const { searchOpen, setSearchOpen, openConversation } = useApp();
  const [query, setQuery] = useState("");

  if (!searchOpen) return null;

  const results = CONVERSATIONS.filter((c) =>
    c.title.toLowerCase().includes(query.toLowerCase()),
  );

  return (
    <div
      className="fixed inset-0 z-50 flex justify-center bg-black/50 pt-[12vh]"
      onClick={() => setSearchOpen(false)}
    >
      <div
        className="h-fit w-full max-w-[600px] overflow-hidden rounded-[14px] border border-border-base bg-bg-2 shadow-2xl"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center gap-2.5 border-b border-border-base px-4 py-3">
          <SearchIcon size={18} className="text-fg-muted" />
          <input
            autoFocus
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Search messages…"
            className="flex-1 bg-transparent text-[15px] text-fg outline-none placeholder:text-fg-muted"
          />
          <kbd className="rounded border border-border-base px-1.5 py-0.5 text-[11px] text-fg-muted">
            Esc
          </kbd>
        </div>
        <div className="max-h-[50vh] overflow-y-auto p-2">
          {results.length === 0 ? (
            <p className="px-3 py-8 text-center text-[14px] text-fg-muted">
              No conversations found
            </p>
          ) : (
            results.map((c) => (
              <button
                key={c.id}
                type="button"
                onClick={() => {
                  openConversation(c.id);
                  setSearchOpen(false);
                }}
                className="flex w-full items-center gap-3 rounded-[8px] px-3 py-2.5 text-left transition-colors hover:bg-bg-hover"
              >
                <span className="text-[16px] leading-none">{c.emoji}</span>
                <span className="truncate text-[14px] text-fg">{c.title}</span>
              </button>
            ))
          )}
        </div>
      </div>
    </div>
  );
}
