"use client";

import { cn } from "@/lib/utils";
import {
  ArrowLeftIcon,
  BoltIcon,
  CloudIcon,
  CompassIcon,
  GridIcon,
  InfoIcon,
  LogoIcon,
  LogoutIcon,
  MonitorIcon,
  MoonIcon,
  ScreenShareIcon,
  SunIcon,
} from "@/components/icons";
import { useApp } from "./AppContext";

const GROUPS: { label: string; items: { id: string; label: string; icon: React.ReactNode }[] }[] = [
  {
    label: "AI Core",
    items: [
      { id: "agents", label: "Agents", icon: <CompassIcon size={16} /> },
      { id: "model", label: "Model", icon: <CloudIcon size={16} /> },
      { id: "capabilities", label: "Capabilities", icon: <BoltIcon size={16} /> },
    ],
  },
  {
    label: "Application",
    items: [
      { id: "appearance", label: "Appearance", icon: <MonitorIcon size={16} /> },
      { id: "remote", label: "Remote", icon: <ScreenShareIcon size={16} /> },
      { id: "system", label: "System", icon: <GridIcon size={16} /> },
    ],
  },
  {
    label: "Other",
    items: [{ id: "about", label: "About", icon: <InfoIcon size={16} /> }],
  },
];

export function SettingsSidebar() {
  const {
    sidebarCollapsed,
    settingsSection,
    setSettingsSection,
    goHome,
    theme,
    toggleTheme,
  } = useApp();

  return (
    <aside
      className={cn(
        "layout-sider z-40 flex h-full shrink-0 flex-col overflow-hidden border-r border-border-base bg-bg-2",
        "max-md:fixed max-md:inset-y-0 max-md:left-0 max-md:top-9",
        "transition-[width,transform] duration-200 ease-[cubic-bezier(0.34,0.69,0.1,1)]",
        sidebarCollapsed
          ? "w-0 border-r-0 max-md:w-[260px] max-md:-translate-x-full"
          : "w-[260px]",
      )}
    >
      <div className="flex h-full w-[260px] flex-col">
        <div className="flex h-[52px] items-center gap-2.5 px-4">
          <div className="flex h-7 w-7 items-center justify-center rounded-[8px] bg-[#1c1c1e] text-white">
            <LogoIcon size={20} />
          </div>
          <span className="text-[16px] font-semibold text-fg">AionUi</span>
        </div>

        <div className="flex-1 overflow-y-auto px-2 py-2">
          {GROUPS.map((g) => (
            <div key={g.label} className="mb-3">
              <div className="px-2.5 py-1.5 text-[12px] font-medium text-fg-muted">
                {g.label}
              </div>
              {g.items.map((it) => (
                <button
                  key={it.id}
                  type="button"
                  onClick={() => setSettingsSection(it.id)}
                  className={cn(
                    "flex h-9 w-full items-center gap-2.5 rounded-[8px] px-2.5 text-[14px] transition-colors",
                    settingsSection === it.id
                      ? "bg-bg-active text-fg"
                      : "text-fg-secondary hover:bg-bg-hover hover:text-fg",
                  )}
                >
                  <span className="flex w-4 justify-center">{it.icon}</span>
                  <span>{it.label}</span>
                </button>
              ))}
            </div>
          ))}
        </div>

        <div className="flex items-center gap-1 border-t border-border-base px-2 py-2.5">
          <button
            type="button"
            onClick={goHome}
            className="flex h-9 flex-1 items-center gap-2 rounded-[8px] px-2.5 text-[14px] text-fg-secondary transition-colors hover:bg-bg-hover hover:text-fg"
          >
            <ArrowLeftIcon size={15} />
            <span>Back to</span>
          </button>
          <button
            type="button"
            className="flex h-9 items-center gap-2 rounded-[8px] px-2.5 text-[14px] text-fg-secondary transition-colors hover:bg-bg-hover hover:text-fg"
          >
            <LogoutIcon size={16} />
            <span>Logout</span>
          </button>
          <button
            type="button"
            aria-label="Toggle theme"
            onClick={toggleTheme}
            className="flex h-9 w-9 items-center justify-center rounded-[8px] text-fg-secondary transition-colors hover:bg-bg-hover hover:text-fg"
          >
            {theme === "dark" ? <SunIcon size={16} /> : <MoonIcon size={16} />}
          </button>
        </div>
      </div>
    </aside>
  );
}
